import { createSlice } from "@reduxjs/toolkit";
import axios from "../../utils/axios";
import { tab } from "@testing-library/user-event/dist/cjs/convenience/tab.js";
import { SetCurrentConversation } from "./conversation";
import { LogoutUser, UpdateIsLoading } from "./auth";


const initialState = {
    user: {},
    sideBar: {
        open: false,
        type: "CONTACT" //can be STARRED, SHARED or by default CONTACT
    },
    tab: 0,
    snackbar: {
        open: false,
        message: null,
        severity: null,
    },
    users: [],
    friends: [],
    friendRequests: [],
    chat_type: null,
    room_id: null,
    call_logs: [],
};

const slice = createSlice({
    name: 'app',
    initialState,
    reducers: {
        fetchCallLogs(state, action) {
            state.call_logs = action.payload.call_logs;
        },
        fetchUser(state, action) {
            state.user = action.payload.user;
        },
        updateUser(state, action) {
            state.user = action.payload.user;
        },
        toggleSidebar(state, action) {
            state.sideBar.open = !state.sideBar.open;
        },
        updateSidebarType(state, action) {
            state.sideBar.type = action.payload.type;
        },
        updateTab(state, action) {
            state.tab = action.payload.tab;
        },
        openSnackbar(state, action) {
            state.snackbar.open = true;
            state.snackbar.message = action.payload.message;
            state.snackbar.severity = action.payload.severity;
        },
        closeSnackbar(state, action) {
            state.snackbar.open = false;
            state.snackbar.message = null;
            state.snackbar.severity = null;
        },
        updateUsers(state, action) {
            state.users = action.payload.users;
        },
        updateFriends(state, action) {
            state.friends = action.payload.friends;
        },
        updateFriendRequests(state, action) {
            state.friendRequests = action.payload.friendRequests;
        },
        selectConversation(state, action) {
            state.chat_type = "individual";
            state.room_id = action.payload.room_id;
        },
        clearApp(state, action) {
            return initialState;
        }
    }
});

//Reducer
export default slice.reducer;

export const closeSnackbar = () => async (dispatch, getState) => {
    dispatch(slice.actions.closeSnackbar());
};

export function showSnackbar({ severity, message }) {
    return async (dispatch, getState) => {
        dispatch(slice.actions.openSnackbar({
            message, severity,
        }));
        setTimeout(() => {
            dispatch(slice.actions.closeSnackbar())
        }, 5000);
    }
};

export function ToggleSidebar() {
    return async (dispatch, getState) => {
        dispatch(slice.actions.toggleSidebar());
    };
}
export function UpdateSidebarType(type) {
    return async (dispatch, getState) => {
        dispatch(slice.actions.updateSidebarType({ type }));
    };
}

export function UpdateTab(tab) {
    return async (dispatch, getState) => {
        dispatch(slice.actions.updateTab(tab));
    };
}

export const FetchUsers = () => {
    return async (dispatch, getState) => {
        await axios.get("/user/get-users", {
            headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${getState().auth.token}`,
            }
        }).then((response) => {
            // console.log(response);
            dispatch(slice.actions.updateUsers({ users: response.data.data }));
        }).catch((error) => {
            dispatch(LogoutUser());
            dispatch(showSnackbar({ severity: 'error', message: "Session Expired. Please Login again" }));
            console.log(error);
        })
    }
};

