export const FetchCallLogs = () => {
    return async (dispatch, getState) => {
        dispatch(UpdateIsLoading({ isLoading: true, error: false }));
        axios.get("/user/get-call-logs", {
            headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${getState().auth.token}`,
            },
        }).then((response) => {
            // console.log(response);
            dispatch(UpdateIsLoading({ isLoading: false, error: false }));
            dispatch(slice.actions.fetchCallLogs({ call_logs: response.data.data }));
        }).catch((err) => {
            dispatch(UpdateIsLoading({ isLoading: false, error: true }));
            dispatch(LogoutUser());
            dispatch(showSnackbar({ severity: 'error', message: "Session Expired. Please Login again" }));
            console.log(err);
        });
    };
};
