export const UpdateUserProfile = (formValues) => {
    return async (dispatch, getState) => {
        const file = formValues.avatar;
        const formData = new FormData();
        formData.append('file', file);

        // // TODO == Upload the image to the cloud stotage and pass the URL in the avatar
        const response = await axios.post("/media/uploadFile", formData, {
            headers: {
                Authorization: `Bearer ${getState().auth.token}`,
                "Content-Type": "multipart/form-data",
            }
        });

        const fileUrl = response.data.fileUrl;

        axios.post("/user/update-me", { ...formValues, avatar: fileUrl }, {
            headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${getState().auth.token}`,
            },
        }).then((response) => {
            // console.log(response);
            dispatch(slice.actions.updateUser({ user: response.data.user }));
            dispatch(slice.actions.openSnackbar({ severity: "success", message: response.data.message }));
        }).catch((err) => {
            console.log(err);
        });
    };
};

