export const UploadMedia = (data, onUploadProgress) => {
    return async (dispatch, getState) => {
        const file = data.file;
        const formData = new FormData();
        formData.append('file', file);

        try {
            const response = await axios.post("/media/uploadFile", formData, {
                headers: {
                    Authorization: `Bearer ${getState().auth.token}`,
                    "Content-Type": "multipart/form-data",
                },
                onUploadProgress: (progressEvent) => {
                    const percentCompleted = Math.round((progressEvent.loaded * 100) / progressEvent.total);
                    if (onUploadProgress) {
                        onUploadProgress(percentCompleted); // Update the progress
                    }
                }
            });

            // Return the response so that the calling function can use it
            return response;
        } catch (error) {
            console.error("Error uploading media:", error);
            throw error; // Re-throw error to handle it in the calling function
        }
    }
};
